import { Amplify, API, Auth } from 'aws-amplify';
import config from './dev';

// Configurar Amplify con la configuración de dev
Amplify.configure(config);

// Configurar el interceptor para agregar el token automáticamente
API.configure({
    endpoints: [
        {
            name: 'api',
            endpoint: config.API.endpoints[0].endpoint,
            region: config.Auth.region,
            custom_header: async () => {
                try {
                    const session = await Auth.currentSession();
                    const token = session.getIdToken().getJwtToken();
                    console.log('Token obtenido:', token.substring(0, 20) + '...');
                    return {
                        'Authorization': `Bearer ${token}`,
                        'Content-Type': 'application/json'
                    };
                } catch (error) {
                    console.error('Error obteniendo token:', error);
                    return {
                        'Content-Type': 'application/json'
                    };
                }
            }
        }
    ]
});

// Agregar interceptor para logging de peticiones
API.interceptors.request.use(
    (config) => {
        console.log('Haciendo petición a:', config.url);
        console.log('Headers:', config.headers);
        console.log('Datos:', config.data);
        return config;
    },
    (error) => {
        console.error('Error en la petición:', error);
        return Promise.reject(error);
    }
);

// Agregar interceptor para logging de respuestas
API.interceptors.response.use(
    (response) => {
        console.log('Respuesta recibida:', response);
        return response;
    },
    (error) => {
        console.error('Error en la respuesta:', error);
        if (error.message === 'Network Error') {
            console.error('Detalles del error de red:', {
                url: error.config?.url,
                method: error.config?.method,
                headers: error.config?.headers,
                baseURL: error.config?.baseURL
            });
        }
        return Promise.reject(error);
    }
);

// Imprimir la configuración de la API
console.log('Configuración de la API:', {
    endpoint: config.API.endpoints[0].endpoint,
    region: config.Auth.region
});
